INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(78780140, 'Trent', '特伦特', 'トレント', 'Normal Monster', 'Plant', 'EARTH', 5, 1500, 1800, '还在逐渐成长的大树，是森林的守护神。'),
(73988674, 'Tri-and-Guess', '三位一择', '三位一択', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '宣言额外卡组的怪兽卡的种类（融合·同调·超量）才能发动。双方的额外卡组全部确认，宣言的种类的卡数量多的玩家回复3000基本分。'),
(21420702, 'Tri-Blaze Accelerator', '烈焰加农炮-三叉戟式', 'ブレイズ・キャノン－トライデント', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡把自己场上表侧表示存在的1张「烈焰加农炮」送去墓地才能发动。此外，自己的主要阶段时，选择对方场上1只怪兽才能发动。从手卡把1只炎族怪兽送去墓地，选择的对方怪兽破坏并给与对方基本分500分伤害。这个效果发动的回合，自己怪兽不能攻击。'),
(51097887, 'Tri-Brigade Airborne Assault', '铁兽之凶袭', '鉄獣の凶襲', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只兽族·兽战士族·鸟兽族怪兽为对象才能发动。那只怪兽的攻击力以下而种族不同的1只兽族·兽战士族·鸟兽族怪兽从卡组守备表示特殊召唤。这个效果特殊召唤的怪兽的效果直到回合结束时无效化。这个效果的发动后，直到回合结束时自己不是连接怪兽不能从额外卡组特殊召唤。'),
(10019086, 'Tri-Brigade Arms Bucephalus II', '铁兽式强袭机动兵装改“BucephalusⅡ”', '鉄獣式強襲機動兵装改“BucephalusⅡ”', 'Link Monster', 'Winged Beast', 'DARK', NULL, 3500, NULL, '兽族·兽战士族·鸟兽族怪兽3只以上 自己墓地的「铁兽」魔法·陷阱卡是2张以下的场合，这张卡不能从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：在自己对怪兽的特殊召唤成功时，对方不能把效果发动。 ②：自己或对方的怪兽的攻击宣言时才能发动。这张卡以及对方场上的卡全部除外。 ③：这张卡被送去墓地的场合才能发动。从额外卡组把1只兽族·兽战士族·鸟兽族怪兽送去墓地。'),
(33781156, 'Tri-Brigade Arms Mouser', '铁兽式击灭兵装“Mouser”', '鉄獣式撃滅兵装“Mouser”', 'Link Monster', 'Beast', 'EARTH', NULL, 1800, NULL, '兽族·兽战士族·鸟兽族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组·额外卡组把「铁兽式击灭兵装“捕鼠猫”」以外的2张「铁兽」卡送去墓地（同名卡最多1张）。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能从额外卡组特殊召唤。 ②：这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(47163170, 'Tri-Brigade Bearbrumm the Rampant Rampager', '铁兽战线 块击之熊型机装', '鉄獣戦線 塊撃のベアブルム', 'Link Monster', 'Beast', 'FIRE', NULL, 1700, NULL, '「铁兽」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：丢弃2张手卡，以自己的除外状态的1只4星以下的兽族·兽战士族·鸟兽族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「铁兽」魔法·陷阱卡加入手卡。那之后，选1张自己的手卡回到卡组最下面。这个效果的发动后，直到回合结束时自己不是「铁兽」怪兽不能特殊召唤。'),
(26847978, 'Tri-Brigade Ferrijit the Barren Blossom', '铁兽战线 谎花之费丽吉特', '鉄獣戦線 徒花のフェリジット', 'Link Monster', 'Beast', 'EARTH', NULL, 1600, NULL, '兽族·兽战士族·鸟兽族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只4星以下的兽族·兽战士族·鸟兽族怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。 ②：这张卡被送去墓地的场合才能发动。自己抽1张。那之后，选1张自己的手卡回到卡组最下面。'),
(87209160, 'Tri-Brigade Fraktall', '铁兽战线 弗拉克忒尔', '鉄獣戦線 フラクトール', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1900, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地才能发动。从卡组把1只3星以下的兽族·兽战士族·鸟兽族怪兽送去墓地。 ②：从自己墓地把兽族·兽战士族·鸟兽族怪兽任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只兽族·兽战士族·鸟兽族连接怪兽从额外卡组特殊召唤。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。'),
(92269002, 'Tri-Brigade Hammer', '铁兽之击铁', '鉄獣の撃鉄', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从卡组把「铁兽的击铁」以外的1张「铁兽」魔法·陷阱卡加入手卡。 ●从自己墓地把「铁兽」卡任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只「铁兽」连接怪兽从额外卡组无视召唤条件特殊召唤。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能从额外卡组特殊召唤。'),
(50810455, 'Tri-Brigade Kerass', '铁兽战线 凯拉斯', '鉄獣戦線 ケラス', 'Effect Monster', 'Beast', 'EARTH', 2, 1200, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只其他的兽族·兽战士族·鸟兽族怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：从自己墓地把兽族·兽战士族·鸟兽族怪兽任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只兽族·兽战士族·鸟兽族连接怪兽从额外卡组特殊召唤。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。'),
(56196385, 'Tri-Brigade Kitt', '铁兽战线 姬特', '鉄獣戦線 キット', 'Effect Monster', 'Beast', 'FIRE', 2, 700, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把兽族·兽战士族·鸟兽族怪兽任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只兽族·兽战士族·鸟兽族连接怪兽从额外卡组特殊召唤。这个效果的发动后，直到回合结束时自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。 ②：这张卡被送去墓地的场合才能发动。从卡组把「铁兽战线 姬特」以外的1张「铁兽」卡送去墓地。'),
(19096726, 'Tri-Brigade Mercourier', '铁兽鸟 墨丘利耶', '鉄獣鳥 メルクーリエ', 'Effect Monster', 'Winged Beast', 'DARK', 4, 800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：需以「阿不思的落胤」为融合素材的融合怪兽在自己场上存在，对方把怪兽的效果发动时，把手卡·场上的这张卡送去墓地才能发动。那个效果无效。 ②：这张卡被除外的场合才能发动。除「铁兽鸟 墨丘利信使」外的1只「阿不思的落胤」或者有那个卡名记述的怪兽从卡组加入手卡。'),
(14816857, 'Tri-Brigade Nervall', '铁兽战线 纳贝尔', '鉄獣戦線 ナーベル', 'Effect Monster', 'Winged Beast', 'WIND', 1, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把兽族·兽战士族·鸟兽族怪兽任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只兽族·兽战士族·鸟兽族连接怪兽从额外卡组特殊召唤。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。 ②：这张卡被送去墓地的场合才能发动。从卡组把「铁兽战线 纳贝尔」以外的1只「铁兽」怪兽加入手卡。'),
(86379342, 'Tri-Brigade Oath', '铁兽之血盟', '鉄獣の血盟', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只连接怪兽为对象才能发动。从自己的手卡·墓地把和那只怪兽种族不同的1只兽族·兽战士族·鸟兽族怪兽特殊召唤。 ②：自己场上有兽族·兽战士族·鸟兽族怪兽各存在的场合，把墓地的这张卡除外，以对方场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(96378317, 'Tri-Brigade Rendezvous', '铁兽之相遇', '鉄獣の邂逅', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上的连接状态的兽族·兽战士族·鸟兽族怪兽任意数量为对象才能发动。那些怪兽的攻击力直到回合结束时上升700。 ②：自己场上的连接状态的兽族·兽战士族·鸟兽族怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(40975243, 'Tri-Brigade Revolt', '铁兽之御敌', '鉄獣の抗戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的墓地·除外状态的兽族·兽战士族·鸟兽族怪兽任意数量效果无效特殊召唤，只用那些怪兽为素材进行1只「铁兽」连接怪兽的连接召唤。'),
(10793085, 'Tri-Brigade Roar', '铁兽之咆哮', '鉄獣の咆哮', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有连接怪兽存在的场合，从卡组·额外卡组把1张「铁兽」卡送去墓地，以场上1只效果怪兽为对象才能发动。送去墓地的卡种类的以下效果适用。 ●怪兽：作为对象的怪兽的攻击力直到回合结束时变成0。 ●魔法：作为对象的怪兽的效果直到回合结束时无效。 ●陷阱：作为对象的怪兽回到手卡。'),
(52331012, 'Tri-Brigade Rugal the Silver Sheller', '铁兽战线 银弹之卢卡尔', '鉄獣戦線 銀弾のルガル', 'Link Monster', 'Beast-Warrior', 'EARTH', NULL, 2300, NULL, '兽族·兽战士族·鸟兽族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：对方主要阶段才能发动。从自己的手卡·墓地把1只4星以下的兽族·兽战士族·鸟兽族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段回到持有者手卡。 ②：这张卡被送去墓地的场合才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降自己场上的怪兽的种族种类×300。'),
(7889323, 'Tri-Brigade Showdown', '铁兽之死线', '鉄獣の死線', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有兽族·兽战士族·鸟兽族怪兽特殊召唤的场合，以自己的除外状态的1只「铁兽」怪兽为对象才能发动。那只怪兽加入手卡。 ②：自己的「铁兽」怪兽和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽回到手卡。'),
(99726621, 'Tri-Brigade Shuraig the Ominous Omen', '铁兽战线 凶鸟之修莱格', '鉄獣戦線 凶鳥のシュライグ', 'Link Monster', 'Winged Beast', 'DARK', NULL, 3000, NULL, '兽族·兽战士族·鸟兽族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合或者自己场上有这张卡以外的兽族·兽战士族·鸟兽族怪兽特殊召唤的场合才能发动。场上1张卡除外。 ②：这张卡被送去墓地的场合才能发动。把持有自己的除外状态的兽族·兽战士族·鸟兽族怪兽数量以下的等级的1只兽族·兽战士族·鸟兽族怪兽从卡组加入手卡。'),
(19304410, 'Tri-Brigade Springans Kitt', '铁兽守宝团 炎工之姬特', '鉄獣の炎工 キット', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「铁兽炎工 姬特」以外的，「铁兽」怪兽或「护宝炮妖」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被送去墓地的场合才能发动。除「铁兽炎工 姬特」外的以下怪兽之内1只从自己墓地守备表示特殊召唤。 ●「铁兽」怪兽 ●「护宝炮妖」怪兽 ●「阿不思的落胤」或者有那个卡名记述的怪兽'),
(25908748, 'Tri-Brigade Stand-Off', '铁兽之战线', '鉄獣の戦線', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己不是兽族·兽战士族·鸟兽族怪兽不能从额外卡组特殊召唤。 ②：从自己的手卡·场上把1只怪兽送去墓地才能发动。原本种族和送去墓地的怪兽不同的1只「铁兽」怪兽从卡组加入手卡。 ③：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。这个回合对方不能攻击宣言。'),
(68836428, 'Tri-Edge Levia', '三刃戟海龙神', 'トライエッジ・リヴァイア', 'XYZ Monster', 'Sea Serpent', 'WATER', 3, 1800, 1500, '3星怪兽×3 这张卡战斗破坏的怪兽不去墓地从游戏中除外。此外，1回合1次，把这张卡1个超量素材取除，选择场上表侧表示存在的1只怪兽才能发动。直到回合结束时，选择的怪兽的攻击力下降800，效果无效化。这个效果在对方回合也能发动。'),
(52445243, 'Tri-Edge Master', '三刃圣手', 'トライエッジ・マスター', 'Synchro Monster', 'Warrior', 'LIGHT', 6, 2100, 1800, '调整＋调整以外的怪兽1只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。那一组作为同调素材的怪兽的等级组合的以下效果适用。3只以上为素材的场合以下效果全部适用。 ●1星和5星：场上1张其他卡破坏。 ●2星和4星：自己抽1张。 ●3星和3星：这张卡当作调整使用。'),
(32617464, 'Tri-Gate Wizard', '三闸极男巫', 'トライゲート・ウィザード', 'Link Monster', 'Cyberse', 'EARTH', NULL, 2200, NULL, '衍生物以外的怪兽2只以上 ①：得到和这张卡互相连接的怪兽数量的以下效果。 ●1只以上：和这张卡互相连接的怪兽在和对方怪兽进行战斗的场合，那只怪兽给与对方的战斗伤害变成2倍。 ●2只以上：1回合1次，以场上1张卡为对象才能发动。那张卡除外。 ●3只：1回合1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并除外。'),
(39111158, 'Tri-Horned Dragon', '三角龙', 'トライホーン・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 8, 2850, 2350, '以头上生长的3只角为特征的恶魔龙。'),
(96383838, 'Tri-Wight', '三白骨区', 'トライワイトゾーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地3只2星以下的通常怪兽为对象才能发动。那些怪兽特殊召唤。'),
(26285788, 'Trial and Tribulation', '招来的对价', '招来の対価', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合的结束阶段时，这个回合自己从手卡·场上解放的衍生物以外的怪兽数量的以下效果适用。「招来的对价」在1回合只能发动1张。 ●1只：从卡组抽1张卡。 ●2只：选自己墓地2只怪兽加入手卡。 ●3只以上：选场上表侧表示存在的最多3张卡破坏。'),
(77827521, 'Trial of Nightmare', '地狱的裁判', '地獄の裁判', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 900, '将敌人封入棺材里。然后由地狱使者下达判决。'),
(72709014, 'Trial of the Princesses', '王女的试炼', '王女の試練', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「白魔导士 绒儿」「黑魔导师 库兰」才能装备。装备怪兽攻击力上升800。装备怪兽因战斗破坏5星以上的怪兽的回合，可以把装备怪兽和这张卡作为祭品，「白魔导士 绒儿」对应「魔法之国的王女-绒儿」，「黑魔导师 库兰」对应「魔法之国的王女-库兰」从手卡·卡组特殊召唤1只。'),
(45383307, 'Triamid Cruiser', '三形金字塔·巡航机', 'トラミッド・クルーザー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「三形金字塔·巡航机」的③的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，每次岩石族怪兽召唤，自己回复500基本分。 ②：场上有「三形金字塔」怪兽召唤的场合才能发动。自己从卡组抽1张，那之后选1张手卡丢弃。 ③：场地区域的表侧表示的这张卡被送去墓地的场合才能发动。从卡组把1只「三形金字塔」怪兽加入手卡。'),
(69529337, 'Triamid Dancer', '三形金字塔的舞者', 'トラミッド・ダンサー', 'Effect Monster', 'Rock', 'EARTH', 3, 600, 1900, '①：1回合1次，以自己墓地1张「三形金字塔」卡为对象才能发动。那张卡回到卡组，自己场上的岩石族怪兽的攻击力·守备力上升500。 ②：对方回合1次，以自己场上1张「三形金字塔」场地魔法卡为对象才能发动。那张卡送去墓地，从卡组把和那张卡卡名不同的1张「三形金字塔」场地魔法卡发动。'),
(9989792, 'Triamid Fortress', '三形金字塔·大要塞', 'トラミッド・フォートレス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「三形金字塔·大要塞」的③的效果1回合只能使用1次。 ①：场上的岩石族怪兽的守备力上升500。 ②：场上的「三形金字塔」怪兽不会被效果破坏。 ③：场地区域的表侧表示的这张卡被送去墓地的场合，以自己墓地1只「三形金字塔」怪兽为对象才能发动。那只怪兽加入手卡。'),
(95923441, 'Triamid Hunter', '三形金字塔的猎人', 'トラミッド・ハンター', 'Effect Monster', 'Rock', 'EARTH', 3, 1400, 1100, '①：场地魔法卡表侧表示存在的场合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只岩石族怪兽召唤。 ②：对方回合1次，以自己场上1张「三形金字塔」场地魔法卡为对象才能发动。那张卡送去墓地，从卡组把和那张卡卡名不同的1张「三形金字塔」场地魔法卡发动。'),
(72772445, 'Triamid Kingolem', '三形金字塔·巨人王', 'トラミッド・キングゴレム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「三形金字塔·巨人王」的③的效果1回合只能使用1次。 ①：场上的岩石族怪兽的攻击力上升500。 ②：自己的「三形金字塔」怪兽进行战斗的场合，直到伤害步骤结束时对方不能把魔法·陷阱·怪兽的效果发动。 ③：场地区域的表侧表示的这张卡被送去墓地的场合才能发动。从手卡把1只「三形金字塔」怪兽特殊召唤。'),
(64576557, 'Triamid Loading', '古代遗迹的肃静', '古代遺跡の静粛', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在魔法与陷阱区域存在，场地区域有场地魔法卡被表侧表示放置的场合才能发动。从卡组把「古代遗迹的肃静」以外的1张「三形金字塔」魔法·陷阱卡加入手卡。 ②：自己场上的表侧表示的岩石族怪兽被战斗或者对方的效果破坏的场合才能发动。和破坏的怪兽卡名不同的1只「三形金字塔」怪兽从卡组特殊召唤。'),
(32912040, 'Triamid Master', '三形金字塔之主', 'トラミッド・マスター', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 700, '①：1回合1次，把自己场上1张表侧表示的「三形金字塔」卡送去墓地，以场上盖放的1张卡为对象才能发动。那张卡破坏。 ②：对方回合1次，以自己场上1张「三形金字塔」场地魔法卡为对象才能发动。那张卡送去墓地，从卡组把和那张卡卡名不同的1张「三形金字塔」场地魔法卡发动。'),
(96100333, 'Triamid Pulse', '古代遗迹的觉醒', '古代遺跡の目覚め', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，可以从自己墓地把岩石族怪兽或者场地魔法卡合计2张除外，从以下效果选择1个发动。 ●以这张卡以外的场上1张表侧表示的卡为对象才能发动。那张卡破坏。 ●以自己墓地1只岩石族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ●以自己墓地最多3张场地魔法卡为对象才能发动。那些卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(68406755, 'Triamid Sphinx', '三形金字塔的斯芬克斯', 'トラミッド・スフィンクス', 'Effect Monster', 'Rock', 'EARTH', 10, 2500, 2500, '这张卡不能通常召唤，用「三形金字塔」卡的效果才能特殊召唤。 ①：「三形金字塔的斯芬克斯」以外的自己场上的表侧表示的「三形金字塔」卡被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有其他的「三形金字塔」卡存在的场合，这张卡的攻击力·守备力上升自己墓地的场地魔法卡种类×500，对方怪兽只能向「三形金字塔的斯芬克斯」攻击。'),
(12181376, 'Triangle Ecstasy Spark', '三角狂欢电光', 'トライアングル・X・スパーク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的全部「鹰身女郎三姐妹」的攻击力直到回合结束时变成2700。这个回合，对方不能把陷阱卡发动，对方场上的陷阱卡的效果无效化。'),
(11489642, 'Triangle O', '三角阵-O', 'トライアングル－O', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「水晶头骨」「阿育王铁柱」「卡布雷拉石」全部存在的场合才能发动。场上的卡全部破坏。这个回合，自己受到的效果伤害由对方代受。 ②：把墓地的这张卡除外，以自己墓地的「水晶头骨」「阿育王铁柱」「卡布雷拉石」各1只为对象才能发动。那些怪兽回到卡组。那之后，自己抽3张。'),
(32298781, 'Triangle Power', '三角力量', 'トライアングルパワー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上所有以表侧表示存在的1星通常怪兽（衍生物除外）的原本的攻击力·守备力上升2000点。结束阶段时，自己场上存在的1星通常怪兽全部破坏。'),
(26866984, 'Trias Hierarchia', '圣三天阶', 'トリアス・ヒエラルキア', 'Effect Monster', 'Fairy', 'LIGHT', 9, 1900, 2900, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，自己·对方的主要阶段，把自己场上最多3只天使族怪兽解放才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。并且，再让为这个效果发动而解放的怪兽数量的以下效果各能适用。 ●2只以上：对方场上1张卡破坏。 ●3只：自己抽2张。'),
(300202009, 'Tribal Synergy', NULL, NULL, 'Skill Card', 'Mai', NULL, NULL, NULL, NULL, NULL),
(90969892, 'Tribe Drive', '部落冲锋', 'トライブ・ドライブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽的种族是3种类以上的场合才能发动。和自己场上的怪兽相同种族的怪兽从卡组选3只（相同种族最多1只）。对方从那之中随机选1只，自己把那只怪兽加入手卡或特殊召唤。剩下的怪兽用喜欢的顺序回到卡组下面。'),
(33184167, 'Tribe-Infecting Virus', '同族感染病毒', '同族感染ウィルス', 'Effect Monster', 'Aqua', 'WATER', 4, 1600, 1000, '①：丢弃1张手卡，宣言1个种族才能发动。场上的宣言种族的怪兽全部破坏。'),
(86361354, 'Tribe-Shocking Virus', '同族感电病毒', '同族感電ウィルス', 'Effect Monster', 'Thunder', 'WATER', 4, 1700, 1000, '1回合1次，把手卡1只怪兽从游戏中除外才能发动。和为这个效果发动而从游戏中除外的怪兽相同种族的场上表侧表示存在的怪兽全部破坏。'),
(80230510, 'Tribute Burial', '被埋葬的牲祭', '埋葬されし生け贄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，自己作需要怪兽2只解放的上级召唤的场合只有1次，可以不把怪兽2只解放而从自己·对方的墓地把怪兽各1只除外来上级召唤。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。'),
(2903036, 'Tribute Doll', '牲祭人偶', '生け贄人形', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '祭掉自己场上1只怪兽发动。从手卡特殊召唤1只可以通常召唤的7星怪兽。特殊召唤出的怪兽本回合不能攻击。'),
(79759861, 'Tribute to the Doomed', '对死者的供奉', '死者への手向け', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(93983867, 'Trick Box', '戏法箱', 'トリック・ボックス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的「娱乐法师」怪兽被战斗·效果破坏送去墓地的场合，以对方场上1只怪兽为对象才能发动。自己直到结束阶段得到那只怪兽的控制权。那之后，选自己墓地1只「娱乐法师」怪兽在对方场上特殊召唤。这个回合的结束阶段，这个效果特殊召唤的怪兽的控制权回归原本持有者。'),
(37405032, 'Trickstar Aqua Angel', '淘气仙星・水葵天使', 'トリックスター・アクアエンジェル', 'Effect Monster', 'Fairy', 'WATER', 4, NULL, NULL, '这个卡名在规则上也当作「海晶少女」卡使用。这个卡名的①③的效果在决斗中各能使用1次。 ①：自己场上有「淘气仙星」怪兽或「海晶少女」怪兽存在的场合才能发动。这张卡从手卡·墓地特殊召唤。 ②：有这张卡位于所连接区的连接怪兽不会被战斗破坏。 ③：这张卡作为连接素材送去墓地的场合才能发动。对方的手卡·场上（里侧表示）的卡全部确认。'),
(64804137, 'Trickstar Band Drumatis', '淘气仙星乐队・铁线莲鼓手', 'トリックスターバンド・ドラマチス', 'Fusion Monster', 'Fairy', 'LIGHT', 6, 2000, 1000, '「淘气仙星」怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。同名卡不在自己的场上·墓地存在的1张「淘气仙星」卡从卡组加入手卡。 ②：有这张卡位于所连接区的自己的「淘气仙星」连接怪兽的攻击力上升1000。 ③：自己或对方受到效果伤害的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。'),
(91272072, 'Trickstar Band Sweet Guitar', '淘气仙星乐队・苦甜吉他手', 'トリックスターバンド・ギタースイート', 'Fusion Monster', 'Fairy', 'LIGHT', 7, 2200, 1200, '「淘气仙星」连接怪兽＋「淘气仙星」怪兽 ①：和这张卡连接状态的自己的「淘气仙星」连接怪兽的效果给与对方的伤害变成2倍。 ②：每次「淘气仙星」怪兽的效果让对方受到伤害发动。这张卡的攻击力上升那次伤害的数值。 ③：这张卡攻击的回合的结束阶段发动。这张卡的②的效果上升的数值回到0。那之后，可以从自己墓地选1只「淘气仙星」怪兽加入手卡。'),
(41302052, 'Trickstar Bella Madonna', '淘气仙星・颠茄歌后', 'トリックスター・ベラマドンナ', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2800, NULL, '「淘气仙星」怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：连接召唤的这张卡所连接区没有怪兽存在的场合，这张卡不受其他卡发动的效果影响。 ②：这张卡所连接区没有怪兽存在的场合才能发动。给与对方为自己墓地的「淘气仙星」怪兽种类×200伤害。'),
(94626871, 'Trickstar Black Catbat', '淘气仙星・甜蜜魔鬼', 'トリックスター・スイートデビル', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2000, NULL, '「淘气仙星」怪兽2只 ①：只要这张卡在怪兽区域存在，每次这张卡所连接区的怪兽被战斗·效果破坏送去墓地，给与对方200伤害。 ②：每次「淘气仙星」怪兽的效果让对方受到伤害发动。对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降这张卡所连接区的怪兽数量×200。'),
(77307161, 'Trickstar Bloom', '淘气仙星・绽放金雀儿', 'トリックスター・ブルム', 'Link Monster', 'Fairy', 'LIGHT', NULL, 100, NULL, '2星以下的「淘气仙星」怪兽1只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。对方抽1张。 ②：这张卡所连接区的表侧表示的「淘气仙星」怪兽被战斗·效果破坏的场合才能发动。给与对方为对方手卡数量×200伤害。'),
(99890852, 'Trickstar Bouquet', '淘气仙星・花束', 'トリックスター・ブーケ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「淘气仙星」怪兽和场上1只表侧表示怪兽为对象才能发动。那只「淘气仙星」怪兽回到持有者手卡，另1只作为对象的怪兽的攻击力直到回合结束时上升回到手卡的怪兽的原本攻击力数值。'),
(61283655, 'Trickstar Candina', '淘气仙星・堪蒂娜', 'トリックスター・キャンディナ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 400, '①：这张卡召唤时才能发动。从卡组把1张「淘气仙星」卡加入手卡。 ②：只要这张卡在怪兽区域存在，每次对方把魔法·陷阱卡发动给与对方200伤害。'),
(298846, 'Trickstar Colchica', '淘气仙星・秋仙', 'トリックスター・コルチカ', 'Link Monster', 'Fairy', 'LIGHT', NULL, 200, NULL, '连接怪兽以外的「淘气仙星」怪兽1只 自己对「淘气仙星·科尔奇卡」1回合只能有1次特殊召唤，那个效果1回合只能使用1次。 ①：这张卡在墓地存在的状态，自己的「淘气仙星」怪兽的战斗让怪兽被破坏时，把这张卡除外，以那1只破坏的怪兽为对象才能发动。给与对方那只怪兽的攻击力数值的伤害。'),
(98169343, 'Trickstar Corobane', '淘气仙星・卡罗贝恩', 'トリックスター・キャロベイン', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2000, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上的怪兽不存在的场合或者只有「淘气仙星」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：自己的「淘气仙星」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只自己怪兽的攻击力直到回合结束时上升那自身原本攻击力数值。'),
(51011872, 'Trickstar Crimson Heart', '淘气仙星・血腥玛丽', 'トリックスター・ブラッディマリー', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2000, NULL, '「淘气仙星」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次这张卡所连接区有「淘气仙星」怪兽召唤·特殊召唤，自己回复200基本分。 ②：从手卡丢弃1张「淘气仙星」卡才能发动。双方玩家各自从卡组抽1张。这个效果的发动时自己基本分比对方多2000以上的场合，这个效果让自己抽出的数量变成2张。'),
(3792766, 'Trickstar Delfiendium', '淘气仙星・恶鬼翠雀', 'トリックスター・デビルフィニウム', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2200, NULL, '「淘气仙星」怪兽2只以上 ①：这张卡所连接区有「淘气仙星」怪兽存在的场合，这张卡的攻击宣言时以最多有对方场上的连接怪兽数量的除外的自己的「淘气仙星」卡为对象才能发动。那些卡加入手卡。这张卡的攻击力直到回合结束时上升这个效果加入手卡的卡数量×1000。'),
(63181559, 'Trickstar Diffusion', '淘气仙星・扩散结合', 'トリックスター・ディフュージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：可以从以下效果选择1个发动。 ●自己墓地的怪兽作为融合素材除外，把1只「淘气仙星」融合怪兽融合召唤。 ●进行1只「淘气仙星」连接怪兽的连接召唤。 ②：把墓地的这张卡除外，以自己场上1只「淘气仙星」怪兽为对象才能发动。这个回合，只要那只怪兽在自己场上表侧表示存在，对方怪兽只能选择作为对象的怪兽作为攻击对象。'),
(14365823, 'Trickstar Divaridis', '淘气仙星・青绿歌姬', 'トリックスター・ディーヴァリディス', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1800, NULL, '3星以下的「淘气仙星」怪兽2只 ①：「淘气仙星·蒂瓦丽迪丝」在自己场上只能有1只表侧表示存在。 ②：这张卡特殊召唤成功的场合才能发动。给与对方200伤害。 ③：每次对方对怪兽的召唤·特殊召唤成功发动。给与对方200伤害。'),
(62481203, 'Trickstar Festival', '淘气仙星・音乐节', 'トリックスター・フェス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「淘气仙星」怪兽不能召唤·特殊召唤。 ①：在自己场上把2只「淘气仙星衍生物」（天使族·光·1星·攻/守0）特殊召唤。 ②：从额外卡组特殊召唤的自己场上的「淘气仙星」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(86750474, 'Trickstar Foxglove Witch', '淘气仙星・狐手套女巫', 'トリックスター・フォクシーウィッチ', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2200, NULL, '天使族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。给与对方为对方场上的卡数量×200伤害。 ②：连接召唤的这张卡被战斗·效果破坏的场合才能发动。从额外卡组把1只连接2以下的「淘气仙星」怪兽特殊召唤。那之后，给与对方为对方场上的卡数量×200伤害。'),
(88693151, 'Trickstar Fusion', '淘气仙星・结合', 'トリックスター・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只「淘气仙星」融合怪兽融合召唤。 ②：把墓地的这张卡除外，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤。'),
(32448765, 'Trickstar Holly Angel', '淘气仙星・蜀葵天使', 'トリックスター・ホーリーエンジェル', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2000, NULL, '「淘气仙星」怪兽2只 ①：只要这张卡在怪兽区域存在，每次这张卡所连接区有「淘气仙星」怪兽召唤·特殊召唤，给与对方200伤害。 ②：这张卡所连接区的「淘气仙星」怪兽不会被战斗·效果破坏。 ③：每次「淘气仙星」怪兽的效果让对方受到伤害发动。这张卡的攻击力直到回合结束时上升那次伤害的数值。'),
(1410324, 'Trickstar Hoody', '淘气仙星・芙蒂', 'トリックスター・フーディ', 'Effect Monster', 'Fairy', 'LIGHT', 2, 600, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「淘气仙星」融合·连接怪兽的其中任意种存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合才能发动。从卡组把1张「淘气仙星融合」或「淘气仙星扩散融合」加入手卡。'),
(63492244, 'Trickstar Light Arena', '淘气仙星・灯光竞技场', 'トリックスター・ライトアリーナ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己把「淘气仙星」怪兽连接召唤的场合，以作为那些素材的自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽效果无效守备表示特殊召唤。 ②：1回合1次，以对方的魔法与陷阱区域盖放的1张卡为对象才能发动。只要这张卡存在，盖放的那张卡直到结束阶段不能发动，对方在结束阶段必须让那张卡发动或回到手卡。'),
(35371948, 'Trickstar Light Stage', '淘气仙星・灯光舞台', 'トリックスター・ライトステージ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从卡组把1只「淘气仙星」怪兽加入手卡。 ②：1回合1次，以对方的魔法与陷阱区域1张里侧表示卡为对象才能发动。只要这张卡在场地区域存在，那张里侧表示卡直到结束阶段不能发动，对方在结束阶段必须把那张卡发动或送去墓地。 ③：每次自己场上的「淘气仙星」怪兽用战斗·效果给与对方伤害，给与对方200伤害。'),
(98700941, 'Trickstar Lilybell', '淘气仙星・莉莉贝尔', 'トリックスター・リリーベル', 'Effect Monster', 'Fairy', 'LIGHT', 2, 800, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：这张卡可以直接攻击。 ③：这张卡给与对方战斗伤害时，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽加入手卡。'),
(51208046, 'Trickstar Live Stage', '淘气仙星・演唱会舞台', 'トリックスター・ライブステージ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次，发动的回合，自己不是「淘气仙星」怪兽不能特殊召唤。 ①：这张卡的发动时，可以把自己墓地1只「淘气仙星」怪兽加入手卡。 ②：自己场上有「淘气仙星」连接怪兽存在的场合才能发动。把1只「淘气仙星衍生物」（天使族·光·1星·攻/守0）特殊召唤。 ③：对方的魔法与陷阱区域有卡存在的场合才能发动。把1只「淘气仙星衍生物」特殊召唤。'),
(35199656, 'Trickstar Lycoris', '淘气仙星・曼珠诗华', 'トリックスター・マンジュシカ', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1600, 1200, '①：自己·对方回合，把手卡的这张卡给对方观看，以「淘气仙星·曼珠诗华」以外的自己场上1只「淘气仙星」怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽回到手卡。 ②：只要这张卡在怪兽区域存在，每次对方手卡有卡加入，给与对方加入的卡数量×200伤害。'),
(22159429, 'Trickstar Magical Laurel', '淘气仙星・魔法花冠', 'トリックスター・マジカローラ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「淘气仙星」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：1回合1次，装备怪兽用战斗·效果给与对方伤害的场合才能发动。从手卡把1只「淘气仙星」怪兽特殊召唤。'),
(22219822, 'Trickstar Mandrake', '淘气仙星・曼蕾克', 'トリックスター・マンドレイク', 'Effect Monster', 'Fairy', 'LIGHT', 2, NULL, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡送去墓地的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合，以对方的连接怪兽的所连接区1只怪兽为对象才能发动。那只怪兽破坏。'),
(91505214, 'Trickstar Narkissus', '淘气仙星・娜尔姬丝', 'トリックスター・ナルキッス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 1800, '这个卡名的①的效果1回合只能使用1次。 ①：对方受到效果伤害的场合才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，每次对方把手卡·墓地的怪兽的效果发动，给与对方200伤害。'),
(86825114, 'Trickstar Nightshade', '淘气仙星・菲沃斯', 'トリックスター・ヒヨス', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(37683441, 'Trickstar Noble Angel', '淘气仙星・高贵蓝天使', 'トリックスター・ノーブルエンジェル', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2000, NULL, '「淘气仙星」怪兽2只 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「蓝泪」卡加入手卡。 ②：自己的场上或墓地有融合怪兽存在的场合，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：自己或对方受到效果伤害的场合，以场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(21076084, 'Trickstar Reincarnation', '淘气仙星・康乃馨转世', 'トリックスター・リンカーネイション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方手卡全部除外，对方抽出那个数量。 ②：把墓地的这张卡除外，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(59604521, 'Trickstar Rhodode', '淘气仙星・夏克娜捷', 'トリックスター・シャクナージュ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1900, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡丢弃1张「淘气仙星」卡，以自己墓地1只「淘气仙星」连接怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，每次从对方墓地有卡被除外，给与对方那些除外的卡数量×200伤害。'),
(75622824, 'Tricky Spell 4', '诡术师的魔术4', 'トリッキーズ・マジック４', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示的「诡术师」送去墓地才能发动。对方场上的怪兽数量的「诡术师衍生物」（魔法师族·风·5星·攻2000/守1200）在自己场上守备表示特殊召唤。这衍生物不能攻击宣言。'),
(75622825, 'Tricky Token', '诡术师的魔术4', 'トリッキーズ・マジック４', 'Token', 'Spellcaster', NULL, NULL, NULL, NULL, NULL),
(78905039, 'Tricorn the Cacophonous Concert', '响魔从 吹号三角兽', '響魔従トライコーン', 'Tuner Monster', 'Fiend', 'DARK', 2, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合，以持有和自己场上的怪兽的其中任意种相同种族·属性的自己墓地1只怪兽为对象才能发动。那只怪兽加入手卡。'),
(20797524, 'Tricular', '三轮车人', 'トライクラー', 'Effect Monster', 'Machine', 'EARTH', 3, 300, 300, '这张卡被战斗破坏送去墓地时，可以从自己的手卡或者卡组把1只「二轮车人」在自己场上特殊召唤。'),
(39402797, 'Trident Dragion', '三戟天龙', 'トライデント・ドラギオン', 'Synchro Monster', 'Dragon', 'FIRE', 10, 3000, 2800, '龙族调整＋调整以外的龙族怪兽1只以上 这张卡不用同调召唤不能特殊召唤。 ①：这张卡同调召唤时，以自己场上最多2张其他卡为对象才能发动。那些自己的卡破坏。这张卡在这个回合在同1次的战斗阶段中在通常攻击外加上可以作出最多有这个效果破坏的卡数量的攻击。'),
(20474741, 'Trident Warrior', '三叉戟战士', 'トライデント・ウォリアー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1200, '①：这张卡召唤成功时才能发动。从手卡把1只3星怪兽特殊召唤。'),
(12275533, 'Trifortressops', '机动要犀 铁犀三角龙', '機動要犀 トリケライナー', 'Effect Monster', 'Machine', 'DARK', 6, 1600, 2800, '①：对方对3只以上的怪兽的召唤·反转召唤·特殊召唤成功的回合才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡不受其他卡的效果影响，每次双方的准备阶段守备力下降500。这个效果在对方回合也能发动。'),
(96148285, 'Triggered Summon', '诱发召唤', '誘発召喚', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有怪兽特殊召唤时才能发动。双方可以从手卡把1只4星以下的怪兽在场上特殊召唤。'),
(95504778, 'Triggering Wurm', '扳机亚龙', 'トリガー・ヴルム', 'Effect Monster', 'Dragon', 'DARK', 2, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡作为暗属性连接怪兽的连接素材送去墓地的场合才能发动。墓地的这张卡在作为那只连接怪兽所连接区的自己场上攻击表示特殊召唤。这个效果特殊召唤的这张卡不能作为连接素材。 ②：这张卡被连接怪兽的所发动的效果所破坏的场合或者所除外的场合发动。自己从卡组抽1张。'),
(48568432, 'Trigon', '三角火龙', 'トライゴン', 'Union Effect Monster', 'Dragon', 'FIRE', 3, 500, 1700, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的机械族怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽战斗破坏对方怪兽的场合，从自己墓地选择1只机械族·光属性·4星以下的怪兽特殊召唤。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(49725936, 'Triple Burst Dragon', '三发点射龙', 'スリーバーストショット・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 2400, NULL, '衍生物以外的怪兽2只以上 ①：1回合1次，伤害步骤有怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：把这张卡解放，以自己墓地1只连接2以下的怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以从手卡把1只4星以下的龙族怪兽特殊召唤。这个效果在这张卡特殊召唤的回合不能发动。'),
(34796454, 'Triple Star Trion', '三连星之特利恩', '三連星のトリオン', 'Effect Monster', 'Warrior', 'LIGHT', 1, 100, 100, '这张卡作为上级召唤的解放送去墓地的回合的结束阶段时，这张卡可以从墓地特殊召唤。'),
(25311006, 'Triple Tactics Talent', '三战之才', '三戦の才', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这个回合的自己主要阶段对方是已把怪兽的效果发动的场合，可以从以下效果选择1个发动。 ●自己抽2张。 ●对方场上1只怪兽的控制权直到结束阶段得到。 ●把对方手卡确认，选那之内的1张回到卡组。'),
(35269904, 'Triple Tactics Thrust', '三战之号', '三戦の号', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这个回合对方是已把怪兽的效果发动的场合才能发动。从卡组把「三战之号」以外的1张通常魔法·通常陷阱卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。对方场上有怪兽存在的场合，也能不盖放加入手卡。'),
(72632190, 'Triple-Headed Behemoth', '多利多尔多拉', 'ドリ・ドル・ドラ', 'Effect Monster', 'Dragon', 'WIND', 4, 1500, 1200, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：自己场上的表侧表示卡被效果破坏的场合才能发动（伤害步骤也能发动）。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。这个回合的结束阶段，从自己墓地把1只风属性怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成1000。'),
(61254509, 'Tripod Fish', '深海狗母鱼', 'トライポッド・フィッシュ', 'Effect Monster', 'Fish', 'WATER', 3, 300, 1300, '这张卡从墓地的特殊召唤成功时，选择场上1只鱼族·海龙族·水族怪兽才能发动。选择的怪兽的等级上升1星。'),
(45042329, 'Tripwire Beast', '地雷兽', '地雷獣', 'Normal Monster', 'Thunder', 'EARTH', 4, 1200, 1300, '强大的电磁波不停的向周围发射。'),
(3957130, 'Trisborrel Dragon', '三叶枪管龙', 'トゥリスヴァレル・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 2300, NULL, '包含「弹丸」怪兽的龙族·暗属性怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把「速射扳机」「重型扳机」「双式扳机」的其中1张加入手卡。 ②：以自己场上1张表侧表示卡和自己墓地1只龙族·暗属性怪兽为对象才能发动。作为对象的场上的卡破坏，作为对象的墓地的怪兽加入手卡。'),
(52687916, 'Trishula, Dragon of the Ice Barrier', '冰结界之龙 三叉龙', '氷結界の龍 トリシューラ', 'Synchro Monster', 'Dragon', 'WATER', 9, 2700, 2000, '调整＋调整以外的怪兽2只以上 ①：这张卡同调召唤时才能发动。可以把对方的手卡·场上·墓地的卡各最多1张除外（从手卡是随机选）。'),
(15661378, 'Trishula, the Dragon of Icy Imprisonment', '冰狱龙 三叉龙', '氷獄龍 トリシューラ', 'Fusion Monster', 'Dragon', 'WATER', 9, 2700, 2000, '卡名不同的怪兽×3 这张卡用只以自己的手卡·场上的怪兽为素材的融合召唤以及用以下方法才能从额外卡组特殊召唤。 ●把自己场上的上记卡除外的场合可以从额外卡组特殊召唤（不需要「融合」）。 ①：只用原本种族是龙族的怪兽作为素材让这张卡特殊召唤成功的场合才能发动。以自己卡组·对方卡组最上面·对方的额外卡组的顺序来确认并各让1张除外。这个卡名的这个效果1回合只能使用1次。'),
(70980824, 'Trishula, Zero Dragon of the Ice Barrier', '冰结界之还零龙 三叉龙', '氷結界の還零龍 トリシューラ', 'Synchro Monster', 'Dragon', 'WATER', 11, 2700, 2000, '调整＋调整以外的怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡同调召唤时才能发动。对方场上最多3张卡除外。 ②：同调召唤的这张卡被对方破坏的场合才能发动。从自己的额外卡组·墓地把1只「冰结界之龙 三叉龙」攻击力变成3300特殊召唤。对方场上有表侧表示怪兽存在的场合，再让那些怪兽攻击力变成一半，效果无效化。'),
(61159609, 'Trismagistus', '伟魔三贤之书', '三賢者の書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：只要这张卡在魔法与陷阱区域存在，有装备卡装备的「大贤者」怪兽在1回合各有1次不会被战斗破坏。 ②：自己主要阶段才能发动。从手卡把1只4星魔法师族怪兽特殊召唤。 ③：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。从手卡把「大贤者」怪兽任意数量特殊召唤（同名卡最多1张）。'),
(96163807, 'Tristan, Knight of the Underworld', '冥界骑士 崔斯坦', '冥界騎士トリスタン', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, NULL, '①：这张卡召唤成功时，以自己墓地1只守备力0的不死族怪兽为对象才能发动。那张卡加入手卡。 ②：自己场上有这张卡以外的不死族怪兽存在的场合，这张卡的攻击力上升300。'),
(44716748, 'Trito Enneacraft - "exapatisIA"', NULL, NULL, 'Pendulum Flip Effect Monster', 'Machine', 'EARTH', 1, 100, 1000, NULL),
(7436169, 'Trivikarma', '三步维业报', 'トリヴィカルマ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「维萨斯-斯塔弗罗斯特」和对方场上1只效果怪兽为对象才能发动。那只对方怪兽的效果无效，并让作为对象的自己怪兽的攻击力上升那个原本攻击力和原本守备力之内较高方数值的一半。 ②：把墓地的这张卡除外才能发动。把「三步业」以外的有「维萨斯-斯塔弗罗斯特」的卡名记述的1张魔法·陷阱卡从卡组加入手卡。'),
(63323539, 'Trojan Blast', '特洛伊炸弹', 'トロイボム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽的控制权被对方的卡的效果转移给对方玩家时才能发动。那1只怪兽破坏，给与对方基本分那个攻击力数值的伤害。'),
(76384284, 'Trojan Gladiator Beast', '特洛伊剑斗兽', 'トロイの剣闘獣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡把1只名字带有「剑斗兽」的怪兽在对方场上特殊召唤。那之后，从自己卡组抽1张卡。'),
(55013285, 'Troop Dragon', '军队龙', '軍隊竜', 'Effect Monster', 'Dragon', 'WIND', 2, 700, 800, '这张卡被战斗破坏送去墓地的场合，从卡组选1张「军队龙」在自己的场上特殊召唤。之后卡组洗切。'),
(72144675, 'Troposphere', '对流气圈鸟', 'トラファスフィア', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2400, 2000, '这张卡上级召唤的场合，解放的怪兽必须是鸟兽族怪兽。这张卡只要在场上表侧表示存在不受陷阱卡的效果影响。'),
(61538782, 'Truckroid', '卡车机人', 'トラックロイド', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 2000, '这张卡战斗破坏对方怪兽送去墓地时，把破坏怪兽当作装备卡使用给这张卡装备。这张卡的攻击力上升装备的怪兽卡的攻击力数值。'),
(61529473, 'True Draco Apocalypse', '真龙的默示录', '真竜の黙示録', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次，①②的效果在同一连锁上不能发动。 ①：以自己场上1张其他的「真龙」卡为对象才能发动。那张卡破坏，对方场上的全部表侧表示怪兽的攻击力·守备力变成一半。 ②：对方主要阶段才能发动。表侧表示进行1只「真龙」怪兽的上级召唤。 ③：这张卡从魔法与陷阱区域送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(49430782, 'True Draco Heritage', '真龙的继承', '真竜の継承', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己抽出这个回合从场上送去墓地的「真龙」卡种类（怪兽·魔法·陷阱）的数量。 ②：自己主要阶段才能发动。表侧表示进行1只「真龙」怪兽的上级召唤。 ③：这张卡从魔法与陷阱区域送去墓地的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(37984331, 'True Exodia', '真艾克佐迪亚', '真エクゾディア', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '这张卡在怪兽区域存在，这张卡以外的双方场上的怪兽只有「被封印」通常怪兽4种类的场合，从这张卡的控制者来看的对方决斗胜利。'),
(96746083, 'True King Agnimazud, the Vanisher', '真龙皇 炽神焰兽 消隐', '真竜皇アグニマズドV', 'Effect Monster', 'Wyrm', 'FIRE', 9, 2900, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡以外的自己的手卡·场上（表侧表示）的包含炎属性怪兽的2只怪兽破坏，这张卡特殊召唤，把2只炎属性怪兽破坏的场合，可以从对方的场上·墓地把1只怪兽除外。 ②：这张卡被效果破坏的场合才能发动。从自己墓地把1只炎属性以外的幻龙族怪兽加入手卡。'),
(82321037, 'True King Bahrastos, the Fathomer', '真龙皇 渊渎圣子 统领', '真竜皇バハルストスF', 'Effect Monster', 'Wyrm', 'WATER', 9, 1800, 3000, '「真龙皇 巴哈斯督·统领」的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从这张卡以外的手卡以及自己场上的表侧表示怪兽之中把包含水属性怪兽的2只怪兽破坏，这张卡从手卡特殊召唤，把2只水属性怪兽破坏的场合，可以从对方的场上·墓地选最多2张魔法·陷阱卡除外。 ②：这张卡被效果破坏的场合才能发动。从卡组把1只水属性以外的幻龙族怪兽守备表示特殊召唤。'),
(30539496, 'True King Lithosagym, the Disaster', '真龙皇 威岩真主 灾厄', '真竜皇リトスアジムD', 'Effect Monster', 'Wyrm', 'EARTH', 9, 2500, 2300, '「真龙皇 利托斯阿齐姆·灾祸」的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从这张卡以外的手卡以及自己场上的表侧表示怪兽之中把包含地属性怪兽的2只怪兽破坏，这张卡从手卡特殊召唤，把2只地属性怪兽破坏的场合，可以把对方的额外卡组确认并从那之中选怪兽最多3种类除外。 ②：这张卡被效果破坏的场合才能发动。从自己墓地选1只地属性以外的幻龙族怪兽特殊召唤。'),
(88581108, 'True King of All Calamities', '真龙皇 神子灾兽', '真竜皇V.F.D.', 'XYZ Monster', 'Wyrm', 'DARK', 9, 3000, 3000, '9星怪兽×2只以上 ①：1回合1次，把这张卡1个超量素材取除，宣言1个属性才能发动。这个回合，以下效果适用。这个效果在对方回合也能发动。 ●场上的表侧表示怪兽变成宣言的属性，宣言的属性的对方怪兽不能攻击，不能把效果发动。 ②：只要这张卡在怪兽区域存在，自己手卡的「真龙」怪兽的效果破坏的怪兽从对方场上也能选。'),
(35125879, 'True King''s Return', '真龙皇的复活', '真竜皇の復活', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次，①②的效果在同一连锁上不能发动。 ①：以自己墓地1只「真龙」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。 ②：对方主要阶段才能发动。表侧表示进行1只「真龙」怪兽的上级召唤。 ③：这张卡从魔法与陷阱区域送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(62089826, 'True Light', '真之光', '真の光', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●从自己的手卡·墓地把1只「青眼白龙」特殊召唤。 ●同名卡不在自己的场上·墓地存在的1张有「青眼白龙」的卡名记述的魔法·陷阱卡从卡组到自己场上盖放。 ②：对方不能把自己的怪兽区域的「青眼白龙」作为效果的对象。 ③：魔法与陷阱区域的表侧表示的这张卡被送去墓地的场合发动。自己场上的怪兽全部破坏。'),
(87319876, 'Trust Guardian', '信赖守护者', 'トラスト・ガーディアン', 'Tuner Monster', 'Fairy', 'LIGHT', 3, NULL, 800, '把这张卡作为同调素材的场合，不是7星以上的同调怪兽的同调召唤不能使用。这张卡为同调素材的同调怪兽1回合只有1次不会被战斗破坏。这个效果适用的伤害步骤结束时，那只同调怪兽的攻击力·守备力下降400。'),
(77092311, 'Tsuchigumo, the Poisonous Mayakashi', '毒之魔妖－土蜘蛛', '毒の魔妖－土蜘蛛', 'Synchro Monster', 'Zombie', 'EARTH', 5, 2000, 1800, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「毒之魔妖-土蜘蛛」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，原本等级是7星的自己的同调怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地把1只其他的不死族怪兽除外，这张卡特殊召唤。 ③：这张卡从墓地的特殊召唤成功的场合才能发动。从双方卡组上面把3张卡送去墓地。'),
(5325155, 'Tsukahagi, the Poisonous Mayakashi', '毒之魔妖－束胫', '毒の魔妖－束脛', 'Tuner Monster', 'Zombie', 'EARTH', 2, NULL, 2000, '①：「毒之魔妖-束胫」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，「毒之魔妖-束胫」以外的自己的「魔妖」怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡特殊召唤。这个效果发动的回合，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(25334372, 'Tsukumo Slash', '九十九斩', '九十九スラッシュ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「九十九斩」在1回合只能发动1张。 ①：自己怪兽向比那只怪兽攻击力高的怪兽攻击的伤害计算时才能发动。那只进行战斗的自己怪兽的攻击力只在那次伤害计算时上升自己和对方的基本分差的数值。'),
(34853266, 'Tsukuyomi', '月读命', '月読命', 'Spirit Monster', 'Spellcaster', 'DARK', 4, 1100, 1400, '这张卡不能特殊召唤。 ①：这张卡召唤·反转的场合，以场上1只表侧表示怪兽为对象发动。那只怪兽变成里侧守备表示。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(78098950, 'Tsumuha-Kutsunagi the Lord of Swords', '刀皇－都牟羽沓薙', '刀皇－都牟羽沓薙', 'Spirit Monster', 'Warrior', 'WIND', 11, 3000, 3000, '这张卡不能特殊召唤。这张卡可以把1只通常召唤的怪兽解放作上级召唤。 ①：这张卡召唤·反转的场合发动。对方可以选自身场上的卡任意数量送去墓地。那个场合，双方从卡组抽出那个数量。这个效果发动的回合的结束阶段，双方的场上·墓地的卡以及除外中的卡全部回到持有者卡组。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(84635192, 'Tsuru-Puru-Purun', '啾噜噗噜噗珑', 'ツルプルプルン', 'Effect Monster', 'Aqua', 'WATER', 2, 450, 500, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己的主要怪兽区域1只水属性怪兽为对象才能发动。那只自己怪兽破坏，这张卡在那只怪兽存在过的区域特殊召唤。那之后，可以把和这张卡相同纵列的对方的表侧表示卡全部破坏。'),
(27769400, 'Tualatin', '图拉丁', 'テュアラティン', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2500, '对方的战斗阶段时才能发动。战斗阶段开始时自己场上有怪兽2只以上存在，那些怪兽在同1次的战斗阶段中被战斗全部破坏送去墓地时，这张卡可以从手卡特殊召唤。这个效果特殊召唤成功时，宣言1个属性，场上表侧表示存在的宣言的属性的怪兽全部破坏。那之后，只要这张卡在场上表侧表示存在，对方不能把宣言的属性的怪兽召唤·特殊召唤。'),
(74093656, 'Tune Warrior', '调整战士', 'チューン・ウォリアー', 'Normal Tuner Monster', 'Warrior', 'EARTH', 3, 1600, 200, '对任何东西进行调节的电波系战士。虽然总是伸出天线，但接收却不那么好。'),
(47459126, 'Tuned Magician', '调整魔术师', 'チューンド・マジシャン', 'Gemini Monster', 'Spellcaster', 'WIND', 4, 1800, 1600, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●只要这张卡在场上表侧表示存在，这张卡当作调整使用。'),
(50951359, 'Tuner Capture', '调整抓取', 'チューナー・キャプチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方对同调怪兽的同调召唤成功时才能发动。那1只作为同调素材的调整从对方墓地在自己场上特殊召唤。'),
(5609226, 'Tuner''s Barrier', '调整防护罩', 'チューナーズ・バリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只调整发动。直到下个回合的结束阶段时，选择的1只调整不会被战斗或者卡的效果破坏。'),
(85821180, 'Tuner''s High', '调整欣快跑', 'チューナーズ・ハイ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1只怪兽才能发动。和那只怪兽相同种族·属性而等级高1星的1只调整从卡组特殊召唤。'),
(70284332, 'Tuner''s Scheme', '调律师的阴谋', '調律師の陰謀', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上有同调怪兽特殊召唤时才能发动。得到那1只同调怪兽的控制权。这个效果得到控制权的怪兽破坏的场合从游戏中除外。那只怪兽不在场上存在时，这张卡破坏。'),
(96363153, 'Tuning', '调律', '調律', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「同调士」调整加入手卡。那之后，自己卡组最上面的卡送去墓地。'),
(82744076, 'Tuning Gum', '调和口香糖', 'チューニングガム', 'Tuner Monster', 'Fiend', 'DARK', 1, 400, 1200, '「调和口香糖」的①的效果1回合只能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽当作调整使用。这个效果发动的回合，自己不用同调怪兽不能攻击。 ②：只以自己场上的同调怪兽1只为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个发动无效。'),
(54941203, 'Tuning Magician', '调律之魔术师', '調律の魔術師', 'Tuner Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '「调律之魔术师」的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己的灵摆区域有2张「魔术师」卡存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡召唤·特殊召唤成功的场合发动。对方回复400基本分，那之后自己受到400伤害。'),
(92676637, 'Tuningware', '调和支援者', 'チューニング・サポーター', 'Effect Monster', 'Machine', 'LIGHT', 1, 100, 300, '①：把场上的这张卡作为同调素材的场合，这张卡可以当作2星怪兽使用。 ②：这张卡作为同调素材送去墓地的场合发动。自己从卡组抽1张。'),
(60187739, 'Turbo Booster', '一击助推士', 'ワンショット・ブースター', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '自己对怪兽的召唤成功的回合，这张卡可以从手卡特殊召唤。可以把这张卡解放，这个回合和自己怪兽进行战斗的1只对方怪兽破坏。'),
(13574687, 'Turbo Cannon', '一击炮轰士', 'ワンショット・キャノン', 'Synchro Monster', 'Machine', 'FIRE', 3, NULL, NULL, '「一击喷射士」＋调整以外的怪兽1只 1回合1次，把场上表侧表示存在的1只怪兽破坏，给与那个控制者破坏怪兽的攻击力一半数值的伤害。'),
(6142213, 'Turbo Rocket', '一击喷射士', 'ワンショット・ロケット', 'Tuner Monster', 'Machine', 'WIND', 2, NULL, NULL, '这张卡攻击的场合，这张卡不会被战斗破坏。那次伤害计算后，给与对方基本分攻击对象怪兽的攻击力一半数值的伤害。'),
(67270095, 'Turbo Synchron', '涡轮同步士', 'ターボ・シンクロン', 'Tuner Monster', 'Machine', 'WIND', 1, 100, 500, '①：这张卡向攻击表示怪兽攻击宣言时才能发动。攻击对象怪兽变成守备表示。 ②：这张卡的攻击让自己受到战斗伤害时才能发动。把受到的战斗伤害数值以下的攻击力的1只怪兽从手卡特殊召唤。'),
(46195773, 'Turbo Warrior', '涡轮战士', 'ターボ・ウォリアー', 'Synchro Monster', 'Warrior', 'WIND', 6, 2500, 1500, '「涡轮同调士」＋调整以外的怪兽1只以上 6星以上的同调怪兽为攻击对象的这张卡的攻击宣言时，攻击对象怪兽的攻击力直到伤害步骤结束时变成一半。场上的这张卡不会成为6星以下的效果怪兽的效果的对象。'),
(16769305, 'Turbo-Tainted Hot Rod GT19', '魔界造车-GT19', '魔界造車－GT１９', 'Flip Tuner Effect Monster', 'Machine', 'FIRE', 3, 500, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，宣言1～9的任意等级才能发动。这张卡的等级直到回合结束时变成宣言的等级。 ②：反转过的这张卡表侧表示存在的场合，自己·对方的主要阶段，以这张卡以外的自己·对方场上1只表侧表示怪兽为对象才能发动。只用那只怪兽和这张卡为素材作同调召唤。'),
(5786513, 'Turn Silence', '时之沉默－回合静默', '時の沈黙－ターン・サイレンス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的等级上升3星。自己场上有着「光之黄金柜」以及有那个卡名记述的怪兽存在的状态，连锁对方怪兽的效果的发动把这张卡发动的场合，那个对方的效果无效。 ②：有「光之黄金柜」的卡名记述的自己怪兽进行战斗的伤害计算时，把墓地的这张卡除外才能发动。那次战斗阶段结束。'),
(74611888, 'Turnabout', '翻脸不认人', '手のひら返し', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '和原本等级不同等级的怪兽在场上表侧表示存在的场合才能发动。场上的怪兽全部变成里侧守备表示。'),
(95612049, 'Turning of the World', '世界轮转', 'リバース・オブ・ザ・ワールド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把手卡的仪式怪兽解放，从手卡·卡组把「破灭之女神 露茵」或者「终焉之王 迪米斯」仪式召唤。'),
(88559132, 'Turret Warrior', '炮塔战士', 'ターレット・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 5, 1200, 2000, '这张卡可以把自己场上存在的1只战士族怪兽解放，从手卡特殊召唤。这个方法特殊召唤的这张卡的攻击力上升解放怪兽的原本攻击力的数值。'),
(72929454, 'Turtle Bird', '龟鸟', 'タートル・バード', 'Normal Monster', 'Aqua', 'WATER', 6, 1900, 1700, '主要栖息在水中，也能在空中飞翔的珍奇乌龟。'),
(76806714, 'Turtle Oath', '龟的誓言', '亀の誓い', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「蟹龟」的降临必需。若不从场地和手卡把等级直到8以上的卡作为祭品，则「蟹龟」不能降临。'),
(17441953, 'Turtle Raccoon', '龟狸', 'タートル・狸', 'Normal Monster', 'Aqua', 'WATER', 3, 700, 900, '背着乌龟甲壳的狸猫。诱惑敌人进行攻击。'),
(37313348, 'Turtle Tiger', '龟虎', 'タートル・タイガー', 'Normal Monster', 'Aqua', 'WATER', 4, 1000, 1500, '身披甲壳的虎，坚硬的甲壳作守备，尖锐的牙齿作攻击。'),
(59053232, 'Turu-Purun', '啾噜噗珑', 'ツルプルン', 'Normal Monster', 'Aqua', 'WATER', 2, 450, 500, '一只眼的奇妙怪兽。拿起手里的鱼叉，朝向对手一刺。'),
(3149764, 'Tutan Mask', '图坦假面', 'ツタン仮面', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '场上表侧表示存在的1只不死族怪兽为对象的魔法·陷阱卡的发动无效并破坏。'),
(83747250, 'Twilight Cloth', '黄昏之交衣', '黄昏の交衣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。选自己墓地的「光道」怪兽任意数量除外，作为对象的怪兽的攻击力·守备力直到回合结束时上升这个效果除外的怪兽数量×200。 ②：这张卡被「光道」怪兽的效果从卡组送去墓地的场合才能发动。这个回合，自己场上的「光道」怪兽不会被战斗·效果破坏。'),
(57348141, 'Twilight Eraser', '黄昏之抹杀', 'トワイライト・イレイザー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有相同种族而卡名不同的「光道」怪兽2只以上存在的场合，把自己墓地2只「光道」怪兽除外，以场上2张卡为对象才能发动。那些卡除外。 ②：这张卡被「光道」怪兽的效果从卡组送去墓地的场合才能发动。从手卡把1只「光道」怪兽特殊召唤。'),
(76930964, 'Twilight Ninja Getsuga, the Shogun', '黄昏之忍者将军-月牙', '黄昏の忍者将軍－ゲツガ', 'Effect Monster', 'Warrior', 'DARK', 8, 2000, 3000, '这张卡可以把1只「忍者」怪兽解放作上级召唤。「黄昏之忍者将军-月牙」的效果1回合只能使用1次。 ①：这张卡在场上攻击表示存在的场合，以「黄昏之忍者将军-月牙」以外的自己墓地2只「忍者」怪兽为对象才能发动。这张卡变成守备表示，作为对象的怪兽特殊召唤。'),
(79441381, 'Twilight Ninja Jogen', '黄昏之忍者-上弦', '黄昏の忍者－ジョウゲン', 'Pendulum Effect Monster', 'Warrior', 'DARK', 7, 2000, 1000, '①：把手卡1张「忍法」卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(6830480, 'Twilight Ninja Kagen', '黄昏之忍者-下弦', '黄昏の忍者－カゲン', 'Pendulum Effect Monster', 'Warrior', 'DARK', 1, NULL, 2000, '①：把这张卡解放，以自己场上1只「忍者」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升800。'),
(40945356, 'Twilight Ninja Nichirin, the Chunin', '黄昏之中忍-日轮', '黄昏の中忍－ニチリン', 'Effect Monster', 'Warrior', 'DARK', 6, 2300, 1000, '这张卡在规则上也当作「忍者」卡使用。 ①：1回合1次，可以从手卡丢弃1只「忍者」怪兽，从以下效果选择1个发动。这个效果在对方回合也能发动。 ●这个回合，自己场上的「忍者」怪兽以及「忍法」卡不会被战斗·效果破坏。 ●选自己场上1只「忍者」怪兽，那个攻击力直到回合结束时上升1000。'),
(14541657, 'Twilight Ninja Shingetsu', '黄昏之忍者-新月', '黄昏の忍者－シンゲツ', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, 100, '「黄昏之忍者-新月」的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能把其他的「忍者」怪兽作为攻击对象，也不能作为效果的对象。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从卡组把「黄昏之忍者-新月」以外的1只「忍者」怪兽加入手卡。'),
(92595825, 'Twilight Rose Black Knight', '夜蔷薇之黑骑士', '夜薔薇の黒騎士', 'Tuner Monster', 'Plant', 'DARK', 3, 1000, 1000, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己墓地把1只「黑蔷薇龙」或者4星以下的植物族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：只要自己场上有同调怪兽存在，自己场上的植物族怪兽的攻击力上升1000。 ③：以自己场上1只其他的植物族怪兽为对象才能发动。那只怪兽的等级上升或下降1星。'),
(2986553, 'Twilight Rose Knight', '夜蔷薇之骑士', '夜薔薇の騎士', 'Tuner Monster', 'Warrior', 'DARK', 3, 1000, 1000, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的植物族怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能选择植物族怪兽作为攻击对象。'),
(60431417, 'Twilight Twin Dragons', '黄昏之双龙', '黄昏の双龍', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「惩戒之龙」存在的场合，以自己墓地1只「裁决之龙」为对象才能发动。那只怪兽加入手卡。那之后，从自己卡组上面把4张卡送去墓地。 ②：这张卡被「光道」怪兽的效果从卡组送去墓地的场合，以自己墓地1只「惩戒之龙」为对象才能发动。那只怪兽加入手卡。那之后，从自己卡组上面把4张卡除外。'),
(60589682, 'Twin Long Rods #1', '格洛斯', 'グロス', 'Normal Monster', 'Aqua', 'WATER', 3, 900, 700, '用像鞭子一般长的手臂进行攻击。稍远的地方也可以攻击的到。'),
(29692206, 'Twin Long Rods #2', '双尾', 'ツインテール', 'Normal Monster', 'Aqua', 'WATER', 3, 850, 700, '挥舞着两根像鞭子一般的尾巴攻击，水中的生物。'),
(29455728, 'Twin Photon Lizard', '双头光子蜥蜴', 'ツイン・フォトン・リザード', 'Fusion Monster', 'Dragon', 'LIGHT', 6, 2400, 1000, '名字带有「光子」的怪兽×2 把这张卡解放才能发动。解放的这张卡的融合召唤使用过的一组融合素材怪兽从自己墓地特殊召唤。'),
(88477149, 'Twin Pillars of Ice', '极寒冰柱', '極寒の氷柱', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：在自己场上把2只「冰柱衍生物」（水族·水·4星·攻1900/守1200）守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。进行1只水属性怪兽的召唤。'),
(21900719, 'Twin Swords of Flashing Light - Tryce', '闪光之双剑－特莱斯', '閃光の双剣－トライス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '从手卡送去墓地1张卡，这张卡才能进行装备。装备这张卡的怪兽攻击力下降500点。装备这张卡的怪兽在同1个战斗阶段中可以进行2次攻击。'),
(66015185, 'Twin Triangle Dragon', '双三角龙', 'ツイン・トライアングル・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1200, NULL, '衍生物以外的4星以下的龙族怪兽2只 ①：这张卡连接召唤成功时，支付500基本分，以自己墓地1只5星以上的怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合不能攻击。'),
(43898403, 'Twin Twisters', '双龙卷', 'ツインツイスター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以场上最多2张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(70050374, 'Twin-Barrel Dragon', '双管手枪龙', 'ツインバレル・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 200, '这张卡召唤·反转召唤·特殊召唤成功时，选择对方场上存在的1张卡发动。进行2次投掷硬币，2次都是表的场合，选择的卡破坏。'),
(43586926, 'Twin-Headed Behemoth', '多尔·多拉', 'ドル・ドラ', 'Effect Monster', 'Dragon', 'WIND', 3, 1500, 1200, '这个卡名的效果在决斗中只能使用1次。 ①：场上的这张卡被破坏送去墓地的回合的结束阶段才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡的攻击力·守备力变成1000。'),
(78984772, 'Twin-Headed Fire Dragon', '爆炎龙', 'ビッグバンドラゴン', 'Normal Monster', 'Pyro', 'FIRE', 6, 2200, 1700, '宇宙形成时所诞生的龙，那股冲击力使双胞胎龙合体。'),
(54752875, 'Twin-Headed Thunder Dragon', '双头雷龙', '双頭の雷龍', 'Fusion Monster', 'Thunder', 'LIGHT', 7, 2800, 2100, '「雷龙」＋「雷龙」'),
(88132637, 'Twin-Headed Wolf', '双头地狱犬', 'ツインヘッド・ケルベロス', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 1000, '自己的场上有这张卡以外的其他恶魔族怪兽表侧表示存在的场合，这张卡战斗破坏的反转效果怪兽的效果无效化。'),
(24025620, 'Twin-Shield Defender', '双盾防护者', 'ダブル・プロテクター', 'Effect Monster', 'Warrior', 'EARTH', 4, 700, 1600, '自己场上存在的这张卡被战斗破坏送去墓地时，对方场上表侧表示存在的1只怪兽的攻击力直到结束阶段时变成一半数值。'),
(40225398, 'Twin-Sword Marauder', '双剑破坏者', 'ツイン・ブレイカー', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1000, '这张卡向守备表示怪兽攻击的场合，只有1次可以继续攻击。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(82035781, 'Twinheaded Beast', '双头猛兽', 'ツインヘデッド・ビースト', 'Effect Monster', 'Beast', 'FIRE', 6, 1700, 1900, '①：这张卡在同1次的战斗阶段中可以作2次攻击。'),
(300205004, 'Twisted Personality', NULL, NULL, 'Skill Card', 'Yami Marik', NULL, NULL, NULL, NULL, NULL),
(45939841, 'Twister', '龙卷', 'ツイスター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '支付500基本分才能发动。选择场上表侧表示存在的1张魔法·陷阱卡破坏。'),
(83228073, 'Two Thousand Needles', '两千根针', '針二千本', 'Effect Monster', 'Beast', 'EARTH', 5, 2000, 1800, '守备表示的这张卡受到攻击时，若这张卡的守备力超过对方攻击怪兽的攻击力，伤害计算后那只攻击怪兽破坏。'),
(6203182, 'Two Toads with One Sting', '一惜二跳', '一惜二跳', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方墓地1只怪兽为对象才能把这张卡发动。那只怪兽在对方场上效果无效特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：装备怪兽不能攻击，不会成为攻击对象。 ③：装备怪兽成为融合·同调·超量·连接召唤的素材让这张卡被送去墓地的场合才能发动。得到融合·同调·超量·连接召唤的那只怪兽的控制权。'),
(44459942, 'Two-for-One Repair Job', '合损为新', 'ニコイチ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己墓地把1只机械族·暗属性怪兽除外才能发动。把有「马达衍生物」的衍生物名记述的1只怪兽从自己的手卡·卡组·墓地特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的机械族·暗属性怪兽被战斗以外送去墓地的场合，把这张卡除外才能发动。在自己场上把1只「马达衍生物」（机械族·地·1星·攻/守200）攻击表示特殊召唤。'),
(89928517, 'Two-for-One Team', '通贩卖员', '通販売員', 'Effect Monster', 'Warrior', 'LIGHT', 2, 1200, 1200, '①：1回合1次，自己主要阶段才能发动。双方玩家各自把1张手卡给对方观看。给人观看的卡是相同种类的场合，那个种类的以下效果适用。 ●怪兽：双方玩家各自可以把给人观看的怪兽特殊召唤。 ●魔法：双方玩家各自从卡组抽2张。 ●陷阱：双方玩家各自从卡组选2张卡送去墓地。'),
(94119974, 'Two-Headed King Rex', '双头恐龙王', '二頭を持つキング・レックス', 'Normal Monster', 'Dinosaur', 'EARTH', 4, 1600, 1200, '恐龙族中的强力卡。用2个头同时攻击。'),
(25578802, 'Two-Man Cell Battle', '二人小组战斗', 'ツーマンセルバトル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '双方在各自的回合的结束阶段只有1次，可以从手卡特殊召唤1只4星的通常怪兽上场。'),
(57305373, 'Two-Mouth Darkruler', '双口的暗之支配者', '二つの口を持つ闇の支配者', 'Normal Monster', 'Dinosaur', 'EARTH', 3, 900, 700, '同时长有两个嘴巴的恐龙，角能蓄电并在背部放电。'),
(83887306, 'Two-Pronged Attack', '夹击', 'はさみ撃ち', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上存在的2只怪兽和对方场上存在的1只怪兽破坏。'),
(72842870, 'Tyhone', '大炮鸟', 'タイホーン', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1200, 1400, '从口中发射远程炮弹，在深山里炮击威力强劲。'),
(56789759, 'Tyhone #2', '鲜红之龙', 'レッド・ドラゴン', 'Normal Monster', 'Dragon', 'FIRE', 6, 1700, 1900, '吐出火球让周围化为火海的鲜红之龙。'),
(68811206, 'Tyler the Great Warrior', NULL, NULL, 'Effect Monster', 'Warrior', 'EARTH', 8, 3000, 1500, NULL),
(21237481, 'Type Zero Magic Crusher', '零式魔导粉碎机', '零式魔導粉砕機', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每把1张魔法卡从手卡丢弃，给与对方基本分500分的伤害。'),
(14883228, 'Typhoon', '台风', 'タイフーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有魔法·陷阱卡2张以上存在，自己场上没有魔法·陷阱卡存在的场合，这张卡的发动从手卡也能用。 ①：以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(2333365, 'Tyr of the Nordic Champions', '极星将 提尔', '極星將テュール', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2000, 2000, '场上没有这张卡以外的名字带有「极星」的怪兽表侧表示存在的场合，这张卡破坏。只要这张卡在场上表侧表示存在，对方不能选择「极星将 提尔」以外的名字带有「极星」的怪兽作为攻击对象。'),
(83235263, 'Tyranno Infinity', '无限暴龙', 'ディノインフィニティ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, -1, NULL, '①：这张卡的原本攻击力变成除外的自己的恐龙族怪兽数量×1000。'),
(58293343, 'Tyrant Burst Dragon', '暴君爆风龙', 'タイラント・バースト・ドラゴン', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2900, 2500, '这张卡在用「克里底亚之牙」的效果把自己的手卡·场上的「暴君翼」送去墓地的场合才能特殊召唤。 ①：这张卡可以向对方怪兽全部各作1次攻击。 ②：以自己场上1只怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ③：用这张卡的效果把这张卡装备的怪兽攻击力·守备力上升400，同1次的战斗阶段中可以作3次攻击。'),
(15543940, 'Tyrant Dino Fusion', '暴君恐龙结合', 'タイラント・ダイナ・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：「恐龙摔跤手」融合怪兽卡决定的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽只在场上表侧表示存在才有1次不会被战斗·效果破坏。');